alter table public.companies add column paid_cancellation_policy text not null default'credito'check(paid_cancellation_policy in('credito','estorno'));
create table public.customer_credit_movements(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_id uuid not null references public.customers(id),auth_user_id uuid,amount numeric(12,2)not null check(amount<>0),type text not null check(type in('credito_cancelamento','uso')),description text not null,source_payment_id uuid references public.portal_pix_payments(id),created_by uuid,created_at timestamptz not null default now(),unique(source_payment_id,type));create index credits_customer_idx on public.customer_credit_movements(customer_id,created_at desc);create index credits_company_idx on public.customer_credit_movements(company_id,created_at desc);create index credits_user_idx on public.customer_credit_movements(auth_user_id)where auth_user_id is not null;
create table public.pix_refund_requests(id uuid primary key default gen_random_uuid(),company_id uuid not null references public.companies(id),customer_id uuid not null references public.customers(id),auth_user_id uuid,appointment_id uuid not null references public.appointments(id),payment_id uuid not null unique references public.portal_pix_payments(id),amount numeric(12,2)not null check(amount>0),status text not null default'pendente'check(status in('pendente','concluido','recusado')),reviewed_by uuid references public.profiles(id),reviewed_at timestamptz,refund_reference text,response_note text,financial_transaction_id uuid references public.financial_transactions(id),created_at timestamptz not null default now());create index refunds_company_status_idx on public.pix_refund_requests(company_id,status,created_at);create index refunds_customer_idx on public.pix_refund_requests(customer_id);create index refunds_user_idx on public.pix_refund_requests(auth_user_id)where auth_user_id is not null;create index refunds_appointment_idx on public.pix_refund_requests(appointment_id);create index refunds_reviewer_idx on public.pix_refund_requests(reviewed_by)where reviewed_by is not null;create index refunds_financial_idx on public.pix_refund_requests(financial_transaction_id)where financial_transaction_id is not null;
alter table public.customer_credit_movements enable row level security;alter table public.pix_refund_requests enable row level security;create policy credits_select on public.customer_credit_movements for select to authenticated using(auth_user_id=(select auth.uid())or(select private.is_company_member(company_id)));create policy refunds_select on public.pix_refund_requests for select to authenticated using(auth_user_id=(select auth.uid())or(select private.is_company_member(company_id)));revoke all on public.customer_credit_movements,public.pix_refund_requests from public,anon,authenticated;grant select on public.customer_credit_movements,public.pix_refund_requests to authenticated;
create or replace function private.portal_cancel_appointment(p_appointment uuid,p_reason text)returns void language plpgsql security definer set search_path=''as $$declare c public.customers;a public.appointments;co public.companies;p public.portal_pix_payments;begin c:=private.portal_customer();select*into a from public.appointments where id=p_appointment and customer_id=c.id and company_id=c.company_id for update;select*into co from public.companies where id=c.company_id;if a.id is null or a.status not in('agendado','confirmado','pendente')or a.scheduled_at<=now()+make_interval(hours=>co.portal_cancellation_hours)or length(trim(p_reason))<3 then raise exception'Cancelamento fora das regras';end if;update public.appointments set status='cancelado',cancellation_reason='Cancelado pelo portal: '||trim(p_reason)where id=a.id;insert into public.appointment_portal_actions(company_id,customer_id,appointment_id,auth_user_id,action,previous_scheduled_at,reason)values(c.company_id,c.id,a.id,(select auth.uid()),'cancelamento',a.scheduled_at,trim(p_reason));for p in select*from public.portal_pix_payments where appointment_id=a.id and status='confirmado'loop if co.paid_cancellation_policy='credito'then insert into public.customer_credit_movements(company_id,customer_id,auth_user_id,amount,type,description,source_payment_id)values(c.company_id,c.id,(select auth.uid()),p.amount,'credito_cancelamento','Crédito por cancelamento do agendamento',p.id)on conflict(source_payment_id,type)do nothing;else insert into public.pix_refund_requests(company_id,customer_id,auth_user_id,appointment_id,payment_id,amount)values(c.company_id,c.id,(select auth.uid()),a.id,p.id,p.amount)on conflict(payment_id)do nothing;end if;end loop;end$$;
create function public.review_pix_refund(p_refund uuid,p_complete boolean,p_reference text,p_note text default null)returns void language plpgsql security invoker set search_path=''as $$declare c uuid;r public.pix_refund_requests;f uuid;begin select company_id into c from public.profiles where id=(select auth.uid())and is_active and role=any(array['proprietario','administrador','gerente','caixa']);if c is null then raise exception'Acesso negado';end if;select*into r from public.pix_refund_requests where id=p_refund and company_id=c for update;if not found or r.status<>'pendente'then raise exception'Estorno indisponível';end if;if p_complete then if length(trim(p_reference))<3 then raise exception'Informe a referência do estorno';end if;insert into public.financial_transactions(company_id,type,category,description,amount,due_date,payment_date,status,payment_method,customer_id,created_by)values(c,'despesa','Estorno Pix','Estorno manual de pagamento Pix',r.amount,current_date,current_date,'pago','pix',r.customer_id,(select auth.uid()))returning id into f;update public.pix_refund_requests set status='concluido',reviewed_by=(select auth.uid()),reviewed_at=now(),refund_reference=trim(p_reference),response_note=p_note,financial_transaction_id=f where id=r.id;else update public.pix_refund_requests set status='recusado',reviewed_by=(select auth.uid()),reviewed_at=now(),response_note=p_note where id=r.id;end if;end$$;
revoke all on function public.review_pix_refund(uuid,boolean,text,text)from public,anon;grant execute on function public.review_pix_refund(uuid,boolean,text,text)to authenticated;create trigger audit_customer_credits after insert or update or delete on public.customer_credit_movements for each row execute function private.capture_audit_log();create trigger audit_pix_refunds after insert or update or delete on public.pix_refund_requests for each row execute function private.capture_audit_log();
